export type AssetId = keyof typeof ASSET_LIBRARY;

/**
 * 호그와트 관련 키워드 → 에셋 키 매핑
 */
export const HOGWARTS_KEYWORDS: Record<string, string> = {
    'harry': 'hogwarts',
    'potter': 'hogwarts',
    '해리': 'hogwarts',
    '해리포터': 'hogwarts',
    '호그와트': 'hogwarts',
    'hogwarts': 'hogwarts',
    'wizarding': 'hogwarts',
    '마법학교': 'hogwarts',
};

/**
 * 키워드로 에셋 경로 찾기
 */
export function findAssetByKeyword(keyword: string): string | null {
    const lower = keyword.toLowerCase();

    // 1. HOGWARTS_KEYWORDS 먼저 확인
    for (const [kw, assetKey] of Object.entries(HOGWARTS_KEYWORDS)) {
        if (lower.includes(kw)) {
            if (ASSET_LIBRARY[assetKey]) {
                return ASSET_LIBRARY[assetKey];
            }
        }
    }

    // 2. ASSET_LIBRARY 직접 매칭
    for (const [key, path] of Object.entries(ASSET_LIBRARY)) {
        if (lower.includes(key.toLowerCase()) || key.toLowerCase().includes(lower)) {
            return path;
        }
    }

    return null;
}

/**
 * 랜덤 변형 선택 (같은 종류의 여러 에셋 중 무작위)
 */
export function getRandomVariant(baseKey: string): string | null {
    return ASSET_LIBRARY[baseKey] || null;
}
